const $=(s,c=document)=>c.querySelector(s);const $$=(s,c=document)=>[...c.querySelectorAll(s)];
const months=['января','февраля','марта','апреля','мая','июня','июля','августа','сентября','октября','ноября','декабря'];
const days=['воскресенье','понедельник','вторник','среда','четверг','пятница','суббота'];
const now=new Date();$('#current-date').textContent=`${days[now.getDay()]}, ${now.getDate()} ${months[now.getMonth()]}`;
let currentView='today';const viewHistory=[];
function showView(id,remember=true){if(id===currentView)return;if(remember)viewHistory.push(currentView);currentView=id;$$('.view').forEach(v=>v.classList.toggle('active',v.id===id));$$('.bottom-nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===id));scrollTo({top:0,behavior:'smooth'})}
function goBack(){const previous=viewHistory.pop()||'today';showView(previous,false)}
$$('[data-view]').forEach(b=>b.onclick=()=>showView(b.dataset.view));$$('[data-back]').forEach(b=>b.onclick=goBack);
const modal=$('#modal'),content=$('#modal-content');$('.modal-close').onclick=()=>modal.close();
function setTheme(theme){document.documentElement.dataset.theme=theme;localStorage.setItem('orbita-theme',theme);document.querySelector('meta[name="theme-color"]').content=theme==='dark'?'#090817':'#E7E8D6'}
function openMenu(){const dark=document.documentElement.dataset.theme==='dark';content.innerHTML=`<div class="app-menu"><div class="eyebrow">МЕНЮ</div><h2>Орбита</h2><button data-menu-view="profile">Профиль <span>→</span></button><button data-theme-toggle>${dark?'Светлая':'Тёмная'} тема <span>${dark?'☼':'☾'}</span></button></div>`;modal.showModal();$$('[data-menu-view]',content).forEach(button=>button.onclick=()=>{modal.close();showView(button.dataset.menuView)});$('[data-theme-toggle]',content).onclick=()=>{setTheme(dark?'light':'dark');modal.close();toast(dark?'Светлая тема включена':'Тёмная тема включена')}}
$('[data-action="menu"]').onclick=openMenu;
setTheme(document.documentElement.dataset.theme||'light');
const escapeHTML=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
const apiBase=(window.ORBITA_API_URL||'').replace(/\/$/,'');
const planetNames={Sun:'Солнце',Moon:'Луна',Mercury:'Меркурий',Venus:'Венера',Mars:'Марс',Jupiter:'Юпитер',Saturn:'Сатурн',Uranus:'Уран',Neptune:'Нептун',Pluto:'Плутон','True Node':'Северный узел'};
const signNames={Aries:'Овен',Taurus:'Телец',Gemini:'Близнецы',Cancer:'Рак',Leo:'Лев',Virgo:'Дева',Libra:'Весы',Scorpio:'Скорпион',Sagittarius:'Стрелец',Capricorn:'Козерог',Aquarius:'Водолей',Pisces:'Рыбы'};
function zodiac(longitude){const signs=['Овен','Телец','Близнецы','Рак','Лев','Дева','Весы','Скорпион','Стрелец','Козерог','Водолей','Рыбы'];return `${(longitude%30).toFixed(1)}° ${signs[Math.floor((longitude%360)/30)]}`}
function toast(t){const x=$('#toast');x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),2200)}
const readProfile=()=>JSON.parse(localStorage.getItem('orbita-profile')||'null');
const readPartner=()=>JSON.parse(localStorage.getItem('orbita-partner')||'null');
const profileComplete=p=>p&&p.birthdate&&p.birthtime&&p.timezone&&p.latitude&&p.longitude;
function dateInZone(zone){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const get=t=>parts.find(x=>x.type===t).value;return `${get('year')}-${get('month')}-${get('day')}`}
function profileSignature(p){return [p.birthdate,p.birthtime,p.timezone,p.latitude,p.longitude].join('|')}
function chartRequest(p){return {birth_datetime:`${p.birthdate}T${p.birthtime}:00`,timezone:p.timezone,latitude:Number(p.latitude),longitude:Number(p.longitude),house_system:'P'}}
let currentChart=null,currentPartnerChart=null,currentForecastKey='';
async function loadChart(profile,force=false){const key=`orbita-chart:v3:${dateInZone(profile.timezone)}:${profileSignature(profile)}`;if(!force){const cached=localStorage.getItem(key);if(cached)return JSON.parse(cached)}const response=await fetch(`${apiBase}/v1/natal-chart`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(chartRequest(profile))});const payload=await response.json();if(!response.ok)throw new Error(payload.detail||'Ошибка расчёта');localStorage.setItem(key,JSON.stringify(payload));return payload}
function bindPlaceSearch(form,query,results,state){let timer;query.oninput=()=>{clearTimeout(timer);form.elements.latitude.value='';form.elements.longitude.value='';form.elements.timezone.value='';results.replaceChildren();const value=query.value.trim();if(value.length<2)return;timer=setTimeout(async()=>{state.textContent='Ищем место…';try{const response=await fetch(`${apiBase}/v1/places/search?q=${encodeURIComponent(value)}`);if(!response.ok)throw new Error();const places=await response.json();state.textContent=places.length?'Выберите место из списка':'Ничего не найдено';results.replaceChildren(...places.map(place=>{const button=document.createElement('button');button.type='button';button.textContent=place.label;button.onclick=()=>{query.value=place.label;form.elements.latitude.value=place.latitude;form.elements.longitude.value=place.longitude;form.elements.timezone.value=place.timezone;results.replaceChildren();state.textContent=`Часовой пояс: ${place.timezone}`};return button}))}catch{state.textContent='Не удалось выполнить поиск. Попробуйте ещё раз.'}},350)}}
function requireProfile(title){content.innerHTML=`<div class="result-copy empty-result"><div class="eyebrow">${title}</div><h2>Сначала заполни профиль рождения</h2><p>Без даты рождения персональный результат не формируется. Для натальной карты также нужны точное время и выбранное из списка место.</p><button class="primary-btn" id="go-profile">Перейти в профиль</button></div>`;modal.showModal();$('#go-profile').onclick=()=>{modal.close();showView('profile')}}
async function openNatal(){const profile=readProfile();if(!profileComplete(profile)){requireProfile('МОЯ НАТАЛЬНАЯ КАРТА');return}content.innerHTML=`<div class="loading-card"><span>☉</span><h2>Открываем твою карту</h2><p>Проверяем сохранённый расчёт…</p></div>`;modal.showModal();try{currentChart=await loadChart(profile);renderNatal(currentChart,profile.name||'')}catch(error){content.innerHTML=`<div class="result-copy"><h2>Не удалось загрузить карту</h2><p>${escapeHTML(error.message)}</p></div>`}}
const signStyle={Aries:'брать инициативу и быстро переходить к делу',Taurus:'создавать устойчивость и двигаться без спешки',Gemini:'собирать информацию, общаться и видеть несколько вариантов',Cancer:'заботиться, чувствовать атмосферу и защищать близких',Leo:'проявляться ярко, вести за собой и получать признание',Virgo:'наводить порядок, замечать детали и улучшать результат',Libra:'искать баланс, договариваться и учитывать обе стороны',Scorpio:'идти в глубину, замечать скрытое и выдерживать сильные эмоции',Sagittarius:'мыслить широко, учиться и искать новые возможности',Capricorn:'ставить цель, брать ответственность и строить надолго',Aquarius:'думать независимо, искать новое и объединять людей вокруг идеи',Pisces:'тонко чувствовать, сопереживать и действовать через интуицию'};
const signWatch={Aries:'не решать всё на первом импульсе',Taurus:'не держаться за привычное только из страха перемен',Gemini:'не распыляться и доводить важное до конца',Cancer:'не прятать свои потребности за заботой о других',Leo:'не связывать самооценку только с чужим одобрением',Virgo:'не требовать от себя и других идеального результата',Libra:'не откладывать решение ради внешнего спокойствия',Scorpio:'не превращать осторожность в контроль и недоверие',Sagittarius:'не обещать больше, чем реально получится сделать',Capricorn:'не измерять свою ценность только достижениями',Aquarius:'не уходить в отстранённость, когда нужна близость',Pisces:'проверять догадки фактами и сохранять личные границы'};
const houseTheme={1:'самопрезентация, тело и личная инициатива',2:'деньги, чувство опоры и личные ценности',3:'общение, обучение и повседневные контакты',4:'дом, семья и внутреннее чувство безопасности',5:'творчество, романтика, удовольствие и самовыражение',6:'работа, привычки, здоровье и ежедневный ритм',7:'партнёрство, близкие отношения и договорённости',8:'доверие, общие ресурсы и глубокие перемены',9:'образование, путешествия, убеждения и поиск смысла',10:'карьера, статус и долгосрочные цели',11:'друзья, сообщества и планы на будущее',12:'внутренний мир, восстановление и скрытые переживания'};
const planetRole={Sun:'самооценка, воля и ощущение своего пути',Moon:'эмоции, привычные реакции и чувство безопасности',Mercury:'мышление, речь и способ воспринимать информацию',Venus:'симпатии, близость, вкус и личные ценности',Mars:'напор, сексуальная энергия, границы и способ действовать',Jupiter:'рост, вера в себя и расширение возможностей',Saturn:'ответственность, ограничения и умение строить надолго',Uranus:'свобода, независимость и отношение к переменам',Neptune:'интуиция, идеалы, фантазия и чувствительность',Pluto:'контроль, кризисы и глубокая внутренняя перестройка','True Node':'направление развития и непривычный жизненный опыт'};
const planetRoleAccusative={Sun:'самооценку, волю и ощущение своего пути',Moon:'эмоции, привычные реакции и чувство безопасности',Mercury:'мышление, речь и способ воспринимать информацию',Venus:'симпатии, близость, вкус и личные ценности',Mars:'напор, сексуальную энергию, границы и способ действовать',Jupiter:'рост, веру в себя и расширение возможностей',Saturn:'ответственность, ограничения и умение строить надолго',Uranus:'свободу, независимость и отношение к переменам',Neptune:'интуицию, идеалы, фантазию и чувствительность',Pluto:'контроль, кризисы и глубокую внутреннюю перестройку','True Node':'направление развития и непривычный жизненный опыт'};
const planetAgreement={Sun:'связано',Moon:'связана',Venus:'связана',Mercury:'связан',Mars:'связан',Jupiter:'связан',Saturn:'связан',Uranus:'связан',Neptune:'связан',Pluto:'связан','True Node':'связан'};
const aspectNames={conjunction:'соединение',sextile:'секстиль',square:'квадрат',trine:'тригон',opposition:'оппозиция'};
const aspectCopy={conjunction:'Эти две темы включаются одновременно и усиливают друг друга. Важно научиться пользоваться ими как одним инструментом.',sextile:'Между темами есть возможность для сотрудничества. Потенциал раскрывается, когда человек сам начинает им пользоваться.',trine:'Темы поддерживают друг друга естественно. Это сильная сторона, которую легко не замечать именно потому, что она даётся без большого напряжения.',square:'Темы спорят между собой и могут давать повторяющееся внутреннее напряжение. Задача — не подавлять одну сторону, а найти рабочий способ соединить обе.',opposition:'Темы проявляются как два полюса. Баланс появляется, когда человек перестаёт выбирать только одну сторону и учитывает обе.'};
function interpretationItem(title,meta,text){return `<article class="interpretation-item"><div><strong>${escapeHTML(title)}</strong><small>${escapeHTML(meta)}</small></div><p>${escapeHTML(text)}</p></article>`}
function interpretationSection(title,subtitle,items,open=false){return `<details class="interpretation-section" ${open?'open':''}><summary><span><strong>${title}</strong><small>${subtitle}</small></span><b>＋</b></summary><div class="interpretation-list">${items}</div></details>`}
function planetInSignItems(chart){return Object.entries(chart.planets).map(([key,point])=>{const planet=planetNames[key]||key,sign=signNames[point.sign]||point.sign,retro=point.retrograde?' · ретроградная фаза':'';const text=`${planet} отвечает за ${planetRoleAccusative[key]||'важную часть характера'}. В знаке ${sign} эта тема проявляется через способность ${signStyle[point.sign]||'действовать в своём стиле'}. Сильная сторона — использовать это осознанно; зона внимания — ${signWatch[point.sign]||'не уходить в крайности'}.`;return interpretationItem(`${planet} в знаке ${sign}`,`${point.degree_in_sign.toFixed(1)}°${retro}`,text)}).join('')}
function planetInHouseItems(chart){return Object.entries(chart.planets).map(([key,point])=>{const planet=planetNames[key]||key,role=planetRole[key]||'личное проявление',sphere=houseTheme[point.house]||'личный опыт';const text=`Тема «${role}» особенно заметна в сфере «${sphere}». Именно здесь чаще возникают события, выборы и задачи, связанные с этой планетой.`;return interpretationItem(`${planet} в ${point.house} доме`,`Сфера: ${sphere}`,text)}).join('')}
function natalAspectItems(chart){if(!chart.aspects?.length)return interpretationItem('Крупных аспектов не найдено','В пределах выбранных орбисов','Это не означает отсутствия связей в карте: просто основные планеты не образуют точных мажорных аспектов в пределах используемых допусков.');return chart.aspects.map(row=>{const left=planetNames[row.from]||row.from,right=planetNames[row.to]||row.to,name=aspectNames[row.type]||row.type,leftAgreement=planetAgreement[row.from]||'связан';const text=`${left} ${leftAgreement} с темой «${planetRole[row.from]}», а ${right} — с темой «${planetRole[row.to]}». ${aspectCopy[row.type]||''}`;return interpretationItem(`${left} — ${right}`,`${name} · орбис ${row.orb.toFixed(1)}°`,text)}).join('')}
function houseInSignItems(chart){return chart.houses.map(house=>{const sign=signNames[house.sign]||house.sign,sphere=houseTheme[house.number]||'эта область жизни';const text=`В сфере «${sphere}» естественный стиль — ${signStyle[house.sign]}. Полезно помнить: ${signWatch[house.sign]}.`;return interpretationItem(`${house.number} дом в знаке ${sign}`,`${house.degree_in_sign.toFixed(1)}° ${sign}`,text)}).join('')}
function renderNatal(chart,person=''){const sun=chart.planets.Sun,moon=chart.planets.Moon;const sunSign=signNames[sun.sign]||sun.sign,moonSign=signNames[moon.sign]||moon.sign,asc=zodiac(chart.angles.ascendant);const sections=interpretationSection('Планеты в знаках','Как проявляются характер, эмоции, мышление и желания',planetInSignItems(chart),true)+interpretationSection('Планеты в домах','В каких сферах жизни сильнее проявляется каждая планета',planetInHouseItems(chart))+interpretationSection('Аспекты','Как планеты поддерживают или напрягают друг друга',natalAspectItems(chart))+interpretationSection('Дома в знаках','В каком стиле раскрывается каждая жизненная сфера',houseInSignItems(chart));content.innerHTML=`<div class="result-copy natal-result"><div class="eyebrow">${person?`КАРТА · ${escapeHTML(person)}`:'НАТАЛЬНАЯ КАРТА'} · SWISS EPHEMERIS</div><div class="result-wheel"><span>☉</span></div><h2>${person?`${escapeHTML(person)}: полная интерпретация`:'Полная интерпретация'}</h2><section class="natal-overview"><div><small>СОЛНЦЕ</small><strong>${sunSign}</strong></div><div><small>ЛУНА</small><strong>${moonSign}</strong></div><div><small>АСЦЕНДЕНТ</small><strong>${asc}</strong></div></section><p class="natal-lead">Карта разобрана по четырём слоям. Начни с планет в знаках, затем посмотри, где именно они проявляются, и только после этого переходи к аспектам и домам.</p><div class="interpretation-sections">${sections}</div><p><small>Положения планет и домов, а также аспекты рассчитаны с помощью Swiss Ephemeris. Интерпретация символическая и не является научным выводом.</small></p><button class="primary-btn" onclick="document.querySelector('#modal').close()">Готово</button></div>`}

function openPartnerForm(){const saved=readPartner()||{};content.innerHTML=`<div class="result-copy partner-flow"><div class="eyebrow">НАТАЛЬНАЯ КАРТА ПАРТНЁРА</div><h2>Данные партнёра</h2><p>Имя можно не указывать. Дата, точное время и место нужны для корректного расчёта домов и асцендента.</p><form id="partner-form" class="natal-form"><label>Имя партнёра <small>необязательно</small><input name="name" value="${escapeHTML(saved.name||'')}" placeholder="Имя партнёра"></label><label>Дата рождения<input name="birthdate" type="date" value="${escapeHTML(saved.birthdate||'')}" required></label><label>Точное время рождения<input name="birthtime" type="time" value="${escapeHTML(saved.birthtime||'')}" required></label><label>Место рождения<input id="partner-place-query" name="birthplace" value="${escapeHTML(saved.birthplace||'')}" autocomplete="off" placeholder="Начните вводить город" required></label><div class="place-results" id="partner-place-results"></div><input name="latitude" type="hidden" value="${escapeHTML(saved.latitude||'')}"><input name="longitude" type="hidden" value="${escapeHTML(saved.longitude||'')}"><input name="timezone" type="hidden" value="${escapeHTML(saved.timezone||'')}"><div class="form-state" id="partner-place-state">${saved.timezone?`Часовой пояс: ${escapeHTML(saved.timezone)}`:'Выберите город из списка'}</div><button class="primary-btn" type="submit">Рассчитать карту партнёра</button></form></div>`;if(!modal.open)modal.showModal();const form=$('#partner-form'),query=$('#partner-place-query');bindPlaceSearch(form,query,$('#partner-place-results'),$('#partner-place-state'));form.onsubmit=async event=>{event.preventDefault();const partner=Object.fromEntries(new FormData(form));if(!profileComplete(partner)){toast('Заполни дату, время и выбери место');return}localStorage.setItem('orbita-partner',JSON.stringify(partner));content.innerHTML=`<div class="loading-card"><span>◎</span><h2>Рассчитываем карту</h2><p>Определяем положения планет и домов…</p></div>`;try{currentPartnerChart=await loadChart(partner,true);renderNatal(currentPartnerChart,partner.name||'Партнёр')}catch(error){content.innerHTML=`<div class="result-copy"><h2>Не удалось рассчитать карту</h2><p>${escapeHTML(error.message)}</p><button class="primary-btn" id="partner-retry">Проверить данные</button></div>`;$('#partner-retry').onclick=openPartnerForm}}}

const arcanaTitles=['Маг','Жрица','Императрица','Император','Иерофант','Влюблённые','Колесница','Справедливость','Отшельник','Колесо Фортуны','Сила','Повешенный','Трансформация','Умеренность','Дьявол','Башня','Звезда','Луна','Солнце','Суд','Мир','Шут'];
const arcanaThemes=['инициатива и способность начинать новое','интуиция и внимательность к скрытым мотивам','созидание, забота и раскрытие ресурсов','структура, ответственность и личные границы','ценности, обучение и передача опыта','выбор, близость и честное партнёрство','движение к цели и управление импульсом','баланс, договорённости и последствия решений','самостоятельный поиск смысла','гибкость в переменах и умение замечать возможности','внутренняя устойчивость и мягкая сила','смена взгляда и принятие необходимой паузы','завершение старого и глубокое обновление','умеренность, ритм и соединение противоположностей','сильные желания, привязанности и материальная энергия','освобождение от неработающих конструкций','надежда, талант и долгосрочное направление','эмоциональная глубина и работа с неопределённостью','ясность, жизненность и открытое самовыражение','переоценка прошлого и зрелый выбор','целостность, завершение и широкий взгляд','свобода, эксперимент и доверие новому опыту'];
function dateDigits(date){return String(date||'').replace(/\D/g,'').split('').map(Number)}
function arcana(...values){const total=values.flatMap(dateDigits).reduce((sum,n)=>sum+n,0);return ((total-1)%22)+1}
function matrixCard(title,number,meaning,action,open=false){const name=arcanaTitles[number-1],theme=arcanaThemes[number-1];return `<details class="reading-card" ${open?'open':''}><summary><span><small>${title} · ЧИСЛО ${number}</small><strong>${name}</strong></span><b>＋</b></summary><div class="reading-points"><p><b>О чём это</b> ${escapeHTML(theme)}.</p><p><b>Как это может проявляться</b> ${escapeHTML(meaning)}</p><p><b>Что попробовать</b> ${escapeHTML(action)}</p></div></details>`}
function openMatrix(){const profile=readProfile();if(!profile?.birthdate){requireProfile('МОЯ МАТРИЦА СУДЬБЫ');return}const base=arcana(profile.birthdate),day=arcana(profile.birthdate.slice(-2)),month=arcana(profile.birthdate.slice(5,7)),year=arcana(profile.birthdate.slice(0,4)),purpose=arcana(String(base),String(year)),relations=arcana(String(day),String(month)),money=arcana(String(month),String(year));const name=escapeHTML(profile.name||'Твоя матрица');content.innerHTML=`<div class="result-copy matrix-result"><div class="eyebrow">МОЯ МАТРИЦА СУДЬБЫ · ${escapeHTML(profile.birthdate)}</div><div class="result-wheel"><span>${base}</span></div><h2>${name}: главное число — ${base}</h2><p>Оно связано с темой «${escapeHTML(arcanaThemes[base-1])}». Открой нужную сферу ниже — внутри коротко написано, как это может проявляться и что с этим делать.</p><div class="matrix-summary"><span><b>${purpose}</b>Рост</span><span><b>${relations}</b>Отношения</span><span><b>${money}</b>Деньги</span></div><div class="reading-cards">${matrixCard('Характер',base,'Ты чаще опираешься на эту модель, когда принимаешь решения или оказываешься в новой ситуации.','Перед важным решением спроси себя: я сейчас использую свою сильную сторону или действую по привычке?',true)}${matrixCard('Внутренний ресурс',day,'Эта тема подсказывает, какие действия быстрее возвращают ощущение опоры и контроля над своей жизнью.','Планируй на неделю хотя бы одно действие, которое действительно даёт тебе силы.')}${matrixCard('Работа и реализация',year,'Такой подход заметнее всего в работе, общении с командой и долгих проектах.','Выбирай задачи, где сильная сторона приносит конкретный и измеримый результат.')}${matrixCard('Личный рост',purpose,'Здесь находится повторяющаяся задача: она может быть сложной, но именно через неё появляется ощущение движения вперёд.','Сформулируй один навык, который хочешь укрепить, и наблюдай прогресс месяц, а не один день.')}${matrixCard('Любовь и близость',relations,'Число показывает привычный способ строить близость и реагировать, когда ожидания партнёров не совпадают.','Говори о потребностях прямо и отделяй факты от догадок о намерениях партнёра.')}${matrixCard('Деньги',money,'Эта тема может проявляться в отношении к расходам, риску, накоплениям и совместным финансовым решениям.','Заранее определи правила для крупных трат и регулярно сверяйся с долгосрочной целью.')}</div><p><small>Матрица — символическая нумерологическая система для саморефлексии, а не научный метод или предсказание.</small></p></div>`;modal.showModal()}

const compatibilityAreas=[{name:'Любовь',description:'Эмоциональное притяжение и способ проявлять чувства.',planets:['Sun','Moon','Venus']},{name:'Быт',description:'Совместный ритм, привычки и чувство надёжности.',planets:['Moon','Saturn']},{name:'Секс',description:'Телесное притяжение, желание и инициатива.',planets:['Venus','Mars','Pluto']},{name:'Дружба',description:'Интерес, поддержка и ощущение команды.',planets:['Mercury','Jupiter','Uranus']},{name:'Партнёрство',description:'Договорённости, верность решениям и общие цели.',planets:['Sun','Moon','Venus','Saturn']},{name:'Веселье',description:'Лёгкость, юмор, спонтанность и впечатления.',planets:['Venus','Jupiter','Uranus']},{name:'Конфликты',description:'Реакция на давление, разницу мнений и границы.',planets:['Mercury','Mars','Saturn','Pluto']},{name:'Бизнес',description:'Роли, решения, ответственность и совместные проекты.',planets:['Sun','Mercury','Jupiter','Saturn']},{name:'Деньги',description:'Отношение к ресурсам, риску и накоплениям.',planets:['Venus','Jupiter','Saturn','Pluto']},{name:'Дети и семья',description:'Забота, правила дома и представления о будущем.',planets:['Moon','Jupiter','Saturn']}];
function angularDistance(a,b){const distance=Math.abs(a-b)%360;return Math.min(distance,360-distance)}
function detectAspect(distance){const types=[['conjunction',0,8],['sextile',60,4],['square',90,6],['trine',120,6],['opposition',180,8]];for(const [type,exact,maxOrb] of types){const orb=Math.abs(distance-exact);if(orb<=maxOrb)return {type,orb}}return null}
function buildSynastry(first,second){const rows=[];for(const [from,a] of Object.entries(first.planets)){for(const [to,b] of Object.entries(second.planets)){const aspect=detectAspect(angularDistance(a.longitude,b.longitude));if(aspect)rows.push({from,to,...aspect})}}return rows.sort((a,b)=>a.orb-b.orb)}
function synastryWeight(type){return {trine:2,sextile:1,conjunction:1,square:-2,opposition:-1}[type]||0}
function compatibilityArea(area,aspects){const relevant=aspects.filter(row=>area.planets.includes(row.from)&&area.planets.includes(row.to));const balance=relevant.reduce((sum,row)=>sum+synastryWeight(row.type)*(1-Math.min(row.orb,8)/10),0);const score=Math.max(1,Math.min(10,Math.round(6+balance/Math.max(1,Math.sqrt(relevant.length)))));return {...area,relevant,score}}
function scoreText(score){if(score>=8)return 'Сильная зона пары: взаимопонимание здесь возникает легче. Всё равно полезно проговаривать ожидания, а не считать совпадение автоматическим.';if(score>=6)return 'Устойчивый потенциал: есть поддерживающие связи и отдельные различия. Лучше всего работают конкретные договорённости.';if(score>=4)return 'Смешанная динамика: притяжение сочетается с напряжением. Эта сфера требует больше внимания и честной обратной связи.';return 'Зона повышенного напряжения: реакции могут задевать уязвимые места обоих. Нужны ясные границы, пауза в конфликте и правила, приемлемые для двоих.'}
function synastryLines(rows,limit=3){if(!rows.length)return '<li>Точных мажорных аспектов в этой сфере не найдено.</li>';return rows.slice(0,limit).map(row=>`<li><strong>${planetNames[row.from]} — ${planetNames[row.to]}</strong><span>${aspectNames[row.type]} · орбис ${row.orb.toFixed(1)}°</span></li>`).join('')}
async function openCompatibility(){const profile=readProfile();if(!profileComplete(profile)){requireProfile('СОВМЕСТИМОСТЬ');return}const partner=readPartner();if(!profileComplete(partner)){content.innerHTML=`<div class="result-copy empty-result"><div class="eyebrow">СОВМЕСТИМОСТЬ ДВУХ КАРТ</div><h2>Сначала рассчитай карту партнёра</h2><p>Для синастрии нужны дата, точное время и место рождения обоих людей. Тогда мы сравним положения планет и аспекты между картами.</p><button class="primary-btn" id="go-partner-chart">Заполнить данные партнёра</button></div>`;modal.showModal();$('#go-partner-chart').onclick=openPartnerForm;return}content.innerHTML=`<div class="loading-card"><span>∞</span><h2>Сравниваем две карты</h2><p>Ищем аспекты между планетами пользователя и партнёра…</p></div>`;modal.showModal();try{[currentChart,currentPartnerChart]=await Promise.all([loadChart(profile),loadChart(partner)]);renderCompatibility(profile,partner,currentChart,currentPartnerChart)}catch(error){content.innerHTML=`<div class="result-copy"><h2>Не удалось рассчитать совместимость</h2><p>${escapeHTML(error.message)}</p></div>`}}
function renderCompatibility(profile,partner,firstChart,secondChart){const aspects=buildSynastry(firstChart,secondChart),areas=compatibilityAreas.map(area=>compatibilityArea(area,aspects)),average=(areas.reduce((sum,item)=>sum+item.score,0)/areas.length).toFixed(1);const strongest=aspects.slice(0,6);content.innerHTML=`<div class="result-copy compatibility-result"><div class="eyebrow">СИНАСТРИЯ · ${escapeHTML(profile.name||'Пользователь')} + ${escapeHTML(partner.name||'Партнёр')}</div><div class="compatibility-total"><span>${average}<small>/10</small></span><div><strong>Общая динамика двух карт</strong><p>Оценка собрана из реальных межпланетных аспектов, а не только из дат рождения.</p></div></div><details class="interpretation-section" open><summary><span><strong>Ключевые аспекты пары</strong><small>Самые точные связи между двумя натальными картами</small></span><b>＋</b></summary><ul class="synastry-list">${synastryLines(strongest,6)}</ul></details><div class="compatibility-grid">${areas.map(item=>`<details class="compatibility-card"><summary><span><strong>${item.name}</strong><small>${item.description}</small></span><b>${item.score}/10</b></summary><div class="compatibility-body"><p>${scoreText(item.score)}</p><ul class="synastry-list">${synastryLines(item.relevant)}</ul></div></details>`).join('')}</div><section class="compatibility-note"><strong>Как читать результат</strong><p>Поддерживающие аспекты показывают, что даётся паре легче. Напряжённые не означают несовместимость — они показывают темы, где особенно нужны зрелые договорённости и бережное поведение.</p></section><p><small>Синастрия — символическая астрологическая интерпретация. Она не оценивает качество отношений и не заменяет реальные поступки партнёров.</small></p></div>`}
function renderForecastModal(forecast){const overview=forecast.overview||{};content.innerHTML=`<div class="result-copy forecast-modal"><div class="eyebrow">ПРОГНОЗ · ${forecast.date}</div><h2>Подробнее о сегодняшнем дне</h2><div class="forecast-detail"><article><strong>Что может проявиться</strong><p>${overview.what_to_expect||forecast.summary}</p></article><article><strong>Для чего день благоприятен</strong><p>${overview.favorable||''}</p></article><article><strong>Чего лучше избегать</strong><p>${overview.avoid||''}</p></article></div><p class="forecast-note"><small>Прогноз описывает символический фон текущих транзитов, а не гарантированные события.</small></p></div>`;modal.showModal()}
function renderSphere(key){const forecast=currentChart?.daily_forecast,sphere=forecast?.spheres?.[key];if(!sphere)return;const names={relationships:'Отношения',work:'Работа',energy:'Энергия'},icons={relationships:'♡',work:'◇',energy:'ϟ'};content.innerHTML=`<div class="result-copy sphere-popup"><div class="eyebrow">СФЕРА ДНЯ · ${forecast.date}</div><div class="result-wheel"><span>${icons[key]}</span></div><h2>${names[key]}</h2><div class="sphere-score">${sphere.score}/10</div><p>${sphere.summary}</p><div class="do-dont"><div><strong>Благоприятно</strong>${sphere.favorable}</div><div><strong>Осторожнее</strong>${sphere.avoid}</div></div><p><small>Оценка отражает текущие транзиты к натальной карте, а не качество самой сферы жизни.</small></p></div>`;modal.showModal()}
function paintToday(forecast){const scores=forecast.scores,overview=forecast.overview||{},key=forecast.key_transit||{};$('#forecast-date').textContent=forecast.date;$('#forecast-headline').textContent=forecast.headline;$('#forecast-summary').textContent=overview.what_to_expect||forecast.summary;['relationships','work','energy'].forEach(name=>{$(`#score-${name}`).textContent=scores[name];$(`#bar-${name}`).style.setProperty('--score',`${scores[name]*10}%`)});$('#transit-title').textContent=key.title||'Спокойный транзитный фон';$('#forecast-advice').textContent=key.explanation||'';$('#transit-practical').textContent=key.advice||'Сохраняй привычный ритм и заверши начатое.'}
async function refreshToday(force=false){const profile=readProfile();if(!profileComplete(profile))return;const key=dateInZone(profile.timezone);if(!force&&currentForecastKey===key)return;currentForecastKey=key;$('#forecast-headline').textContent='Считаем транзиты дня…';try{currentChart=await loadChart(profile,force);paintToday(currentChart.daily_forecast)}catch{$('#forecast-headline').textContent='Прогноз временно недоступен';$('#forecast-summary').textContent='Проверь подключение и попробуй обновить страницу.'}}
const chartFlows={natal:openNatal,partner:openPartnerForm,matrix:openMatrix,couple:openCompatibility};
$$('[data-flow]').forEach(button=>button.onclick=()=>chartFlows[button.dataset.flow]?.());
$('[data-modal="forecast"]').onclick=async()=>{const profile=readProfile();if(!profileComplete(profile)){showView('profile');return}if(!currentChart)currentChart=await loadChart(profile);renderForecastModal(currentChart.daily_forecast)};
$$('[data-sphere]').forEach(button=>button.onclick=async()=>{const profile=readProfile();if(!profileComplete(profile)){showView('profile');return}if(!currentChart)currentChart=await loadChart(profile);renderSphere(button.dataset.sphere)});
const profileForm=$('#profile-form'),profileQuery=$('#profile-place-query');bindPlaceSearch(profileForm,profileQuery,$('#profile-place-results'),$('#profile-place-state'));
profileForm.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));if(!profileComplete(d)){toast('Выбери место из списка');return}localStorage.setItem('orbita-profile',JSON.stringify(d));currentForecastKey='';currentChart=null;$('#today-title').textContent=d.name||'друг';viewHistory.length=0;showView('today',false);toast('Профиль сохранён');refreshToday(true)};
const saved=readProfile();if(saved){Object.entries(saved).forEach(([k,v])=>{const el=profileForm.elements[k];if(el)el.value=v});$('#today-title').textContent=saved.name||'друг';if(saved.timezone)$('#profile-place-state').textContent=`Часовой пояс: ${saved.timezone}`}
refreshToday();setInterval(()=>refreshToday(),60000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshToday()});
const dreamsKey='orbita-dreams:v1';
function readDreams(){try{const value=JSON.parse(localStorage.getItem(dreamsKey)||'[]');return Array.isArray(value)?value:[]}catch{return []}}
function writeDreams(items){localStorage.setItem(dreamsKey,JSON.stringify(items))}
function dreamCountText(count){const mod10=count%10,mod100=count%100;const word=mod10===1&&mod100!==11?'запись':mod10>=2&&mod10<=4&&(mod100<12||mod100>14)?'записи':'записей';return `${count} ${word}`}
function formatDreamDate(value){const [year,month,day]=String(value).split('-').map(Number);if(!year||!month||!day)return 'Дата не указана';return new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long',year:'numeric'}).format(new Date(year,month-1,day))}
function dreamTitle(text){const first=String(text).split(/[.!?\n]/).find(part=>part.trim())?.trim()||'Запись сна';return first.length>48?`${first.slice(0,48).trim()}…`:first}
function openDream(dream){content.innerHTML=`<div class="result-copy dream-detail"><div class="eyebrow">${escapeHTML(formatDreamDate(dream.date))}</div><p class="dream-full-text">${escapeHTML(dream.text)}</p></div>`;modal.showModal()}
function renderDreams(){const list=$('#dream-list'),dreams=readDreams().sort((a,b)=>String(b.date).localeCompare(String(a.date))||Number(b.createdAt||0)-Number(a.createdAt||0));list.replaceChildren();$('#dream-count').textContent=dreamCountText(dreams.length);if(!dreams.length){const empty=document.createElement('div');empty.className='dream-empty';empty.innerHTML='<span>☾</span><strong>Дневник пока пуст</strong><p>Первая сохранённая запись появится здесь.</p>';list.append(empty);return}dreams.forEach(dream=>{const item=document.createElement('button');item.type='button';item.className='dream-item';const icon=document.createElement('span');icon.textContent='☾';const copy=document.createElement('div');const date=document.createElement('small');date.textContent=formatDreamDate(dream.date);const title=document.createElement('strong');title.textContent=dreamTitle(dream.text);const meta=document.createElement('p');meta.textContent='Сохранено на этом устройстве';copy.append(date,title,meta);const arrow=document.createElement('b');arrow.textContent='→';item.append(icon,copy,arrow);item.onclick=()=>openDream(dream);list.append(item)})}
const dreamDate=$('#dream-date');dreamDate.value=new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,10);renderDreams();
$('#dream-form').onsubmit=e=>{e.preventDefault();const text=$('#dream-text').value.trim(),date=dreamDate.value;if(!text||!date)return;const dreams=readDreams();dreams.push({id:`dream-${Date.now()}`,date,text,createdAt:Date.now()});writeDreams(dreams);renderDreams();$('#dream-text').value='';toast('Сон сохранён на устройстве')};
$('[data-action="notifications"]').onclick=()=>toast('Утренний прогноз включён');
